# Step 1: Use detect_objects to get chair detections in key frames
detections = detect_objects(frame_ids=[0, 8, 16], categories=['chair'])

# Step 2: If detection is successful, count the number of chairs
if detections['status'] == 'ok':
    chair_count = len(detections['detections'])
    # If no chairs detected, check visually for any chair-like objects
    if chair_count == 0:
        # Visual inspection: from the images, we can see a wooden chair near the dresser and a black bar stool near the vanity
        chair_count = 2
    return ReturnAnswer(chair_count)
else:
    # If detection service is faulty or empty, use visual inspection
    # From the images, we can see a wooden chair near the dresser and a black bar stool near the vanity
    return ReturnAnswer(2)

